class FacultyFormsetManager{constructor(){this.container=document.getElementById('faculty-items-container');this.totalFormsInput=document.getElementById('id_faculties-TOTAL_FORMS');this.emptyState=document.getElementById('faculty-empty-state');this.counterEl=document.getElementById('faculty-counter');if (!this.container||!this.totalFormsInput)return;this.draggedItem=null;this.dragPlaceholder=null;this.init();}init(){this.attachAddHandler();this.attachItemHandlers();this.updateState();}attachAddHandler(){const addBtn=document.getElementById('faculty-add-btn');if (addBtn){addBtn.addEventListener('click',(e)=>{e.preventDefault();this.addFaculty();});}}addFaculty(){const totalForms=parseInt(this.totalFormsInput.value);const newIndex=totalForms;const item=this.createFacultyItem(newIndex);this.container.appendChild(item);this.totalFormsInput.value=newIndex+1;requestAnimationFrame(()=>{item.classList.add('faculty-item--visible');});this.attachItemHandlers();this.updateState();this.updateSortOrders();const nameInput=item.querySelector('input[name$="-name"]');if (nameInput){setTimeout(()=>nameInput.focus(),150);}}createFacultyItem(index){const item=document.createElement('div');item.className='faculty-item';item.setAttribute('data-faculty-index',index);item.innerHTML=`<div class="faculty-item__drag-handle" title="اسحب لإعادة الترتيب"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="6" r="1.5"/><circle cx="15" cy="6" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="18" r="1.5"/><circle cx="15" cy="18" r="1.5"/></svg></div><div class="faculty-item__content"><div class="faculty-item__number">${index+1}</div><input type="text"
name="faculties-${index}-name"
id="id_faculties-${index}-name"
class="faculty-item__input"
placeholder="اسم الكلية"
dir="rtl"
required><input type="hidden"
name="faculties-${index}-sort_order"
id="id_faculties-${index}-sort_order"
value="${index}"><input type="hidden"
name="faculties-${index}-id"
id="id_faculties-${index}-id"
value=""></div><button type="button" class="faculty-item__delete" title="حذف الكلية"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2m3 0v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6h14"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg></button><input type="hidden"
name="faculties-${index}-DELETE"
id="id_faculties-${index}-DELETE"
value="">`;return item;}deleteFaculty(item){const deleteInput=item.querySelector('input[name$="-DELETE"]');const idInput=item.querySelector('input[name$="-id"]');if (idInput&&idInput.value){deleteInput.value='on';item.classList.add('faculty-item--deleted');setTimeout(()=>{item.style.display='none';this.updateState();this.updateNumbers();},300);}else{item.classList.add('faculty-item--deleted');setTimeout(()=>{item.remove();this.reindexForms();this.updateState();},300);}}reindexForms(){const items=this.container.querySelectorAll('.faculty-item:not([style*="display:none"])');let formIndex=0;const allItems=this.container.querySelectorAll('.faculty-item');allItems.forEach((item,idx)=>{item.setAttribute('data-faculty-index',idx);const inputs=item.querySelectorAll('input');inputs.forEach(input=>{const name=input.getAttribute('name');if (name){input.setAttribute('name',name.replace(/faculties-\d+-/,`faculties-${idx}-`));}const id=input.getAttribute('id');if (id){input.setAttribute('id',id.replace(/id_faculties-\d+-/,`id_faculties-${idx}-`));}});});this.totalFormsInput.value=allItems.length;this.updateNumbers();}updateNumbers(){const visibleItems=this.container.querySelectorAll('.faculty-item:not(.faculty-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const numberEl=item.querySelector('.faculty-item__number');if (numberEl)numberEl.textContent=idx+1;});}updateSortOrders(){const visibleItems=this.container.querySelectorAll('.faculty-item:not(.faculty-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const sortInput=item.querySelector('input[name$="-sort_order"]');if (sortInput)sortInput.value=idx;const numberEl=item.querySelector('.faculty-item__number');if (numberEl)numberEl.textContent=idx+1;});}updateState(){const visibleItems=this.container.querySelectorAll('.faculty-item:not(.faculty-item--deleted):not([style*="display:none"])');const count=visibleItems.length;if (this.emptyState){this.emptyState.style.display=count===0?'flex':'none';}if (this.counterEl){this.counterEl.textContent=count;this.counterEl.style.display=count>0?'inline-flex':'none';}}attachItemHandlers(){this.container.querySelectorAll('.faculty-item__delete').forEach(btn=>{btn.onclick=(e)=>{e.preventDefault();const item=btn.closest('.faculty-item');this.deleteFaculty(item);};});this.container.querySelectorAll('.faculty-item__drag-handle').forEach(handle=>{const item=handle.closest('.faculty-item');item.setAttribute('draggable','true');item.ondragstart=(e)=>this.onDragStart(e,item);item.ondragend=(e)=>this.onDragEnd(e,item);item.ondragover=(e)=>this.onDragOver(e,item);item.ondrop=(e)=>this.onDrop(e,item);});}onDragStart(e,item){this.draggedItem=item;item.classList.add('faculty-item--dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','');}onDragEnd(e,item){item.classList.remove('faculty-item--dragging');this.draggedItem=null;this.container.querySelectorAll('.faculty-item--drag-over').forEach(el=>{el.classList.remove('faculty-item--drag-over');});this.updateSortOrders();this.reindexForms();}onDragOver(e,item){e.preventDefault();e.dataTransfer.dropEffect='move';if (item===this.draggedItem)return;this.container.querySelectorAll('.faculty-item--drag-over').forEach(el=>{el.classList.remove('faculty-item--drag-over');});item.classList.add('faculty-item--drag-over');}onDrop(e,item){e.preventDefault();if (item===this.draggedItem||!this.draggedItem)return;item.classList.remove('faculty-item--drag-over');const allItems=[...this.container.querySelectorAll('.faculty-item:not([style*="display:none"])')];const draggedIdx=allItems.indexOf(this.draggedItem);const targetIdx=allItems.indexOf(item);if (draggedIdx<targetIdx){item.after(this.draggedItem);}else{item.before(this.draggedItem);}}}document.addEventListener('DOMContentLoaded',()=>{new FacultyFormsetManager();});